    //   entry-count-limit                                 32784 bytes  -> inst_entry_count_limit (L5)
    //   file-too-large                                 67108865 bytes  -> l1 (L1)
    //   file-size-at-limit                             67108864 bytes  -> l2 (L2)
    //   entry-count-exactly-4096                          32776 bytes  -> inst_entry_count_exactly_4096 (L4)
    //   count-limit-before-stray-suffix                   32787 bytes  -> inst_count_limit_before_stray_suffix (L5)
    //   invalid-4097th-entry-before-limit                 32784 bytes  -> inst_invalid_4097th_entry_before_limit (L6)
    //   entry-count-followed-by-overflowing-4097th        32784 bytes  -> inst_entry_count_followed_by_overflowing_4097th (L6)
    //   entry-count-before-later-malformed-entry          32792 bytes  -> inst_entry_count_before_later_malformed_entry (L5)

