    #[logic(open)]
    pub fn rgb_rgb_ih32() -> Seq<u8> {
        pearlite! { Seq::create(6912, |i: Int|
            if i % 3 == 0 { ct_rgb_ih32_0()[i / 3] } else if i % 3 == 1 { ct_rgb_ih32_1()[i / 3] } else { ct_rgb_ih32_2()[i / 3] }) }
    }

    #[logic]
    #[requires(mr_model(pl_rgb_ih32(), 2304) == Ok((ct_rgb_ih32_0(), ct_rgb_ih32_1(), ct_rgb_ih32_2())))]
    #[ensures(interleave3(ct_rgb_ih32_0(), ct_rgb_ih32_1(), ct_rgb_ih32_2(), 2304) == rgb_rgb_ih32())]
    pub fn ilv_rgb_ih32() {
        proof_assert!(interleave3(ct_rgb_ih32_0(), ct_rgb_ih32_1(), ct_rgb_ih32_2(), 2304).ext_eq(rgb_rgb_ih32()));
    }

    #[logic]
    #[ensures(mr_model(pl_rgb_ih32(), 2304) == Ok((ct_rgb_ih32_0(), ct_rgb_ih32_1(), ct_rgb_ih32_2())))]
    pub fn mr_rgb_ih32() {
        ch_rgb_ih32_0();
        ch_rgb_ih32_1();
        ch_rgb_ih32_2();
        mr_three(pl_rgb_ih32(), 2304, ct_rgb_ih32_0(), ct_rgb_ih32_1(), ct_rgb_ih32_2(), 36, 72, 108);
    }

