    #[ensures(crate::mc_entry(b_rgb_ih32(), ms_rgb_ih32()[0]) == Ok((48, 48, rgb_rgb_ih32())))]
    pub fn msg_rgb_ih32() {
        eff_rgb_ih32();
        proof_assert!(crate::legacy_colour_model(crate::mentry_type(b_rgb_ih32(), ms_rgb_ih32()[0])) == Some(48u32));
        mr_rgb_ih32();
        ilv_rgb_ih32();
        crate::mc_entry_ok(b_rgb_ih32(), ms_rgb_ih32()[0], 48u32, pl_rgb_ih32(), ct_rgb_ih32_0(), ct_rgb_ih32_1(), ct_rgb_ih32_2(), rgb_rgb_ih32());
    }

