    #[logic(open)]
    pub fn rgb_rgb_it32() -> Seq<u8> {
        pearlite! { Seq::create(49152, |i: Int|
            if i % 3 == 0 { ct_rgb_it32_0()[i / 3] } else if i % 3 == 1 { ct_rgb_it32_1()[i / 3] } else { ct_rgb_it32_2()[i / 3] }) }
    }

    #[logic]
    #[requires(mr_model(pl_rgb_it32(), 16384) == Ok((ct_rgb_it32_0(), ct_rgb_it32_1(), ct_rgb_it32_2())))]
    #[ensures(interleave3(ct_rgb_it32_0(), ct_rgb_it32_1(), ct_rgb_it32_2(), 16384) == rgb_rgb_it32())]
    pub fn ilv_rgb_it32() {
        proof_assert!(interleave3(ct_rgb_it32_0(), ct_rgb_it32_1(), ct_rgb_it32_2(), 16384).ext_eq(rgb_rgb_it32()));
    }

    #[logic]
    #[ensures(mr_model(pl_rgb_it32(), 16384) == Ok((ct_rgb_it32_0(), ct_rgb_it32_1(), ct_rgb_it32_2())))]
    pub fn mr_rgb_it32() {
        ch_rgb_it32_0();
        ch_rgb_it32_1();
        ch_rgb_it32_2();
        mr_three(pl_rgb_it32(), 16384, ct_rgb_it32_0(), ct_rgb_it32_1(), ct_rgb_it32_2(), 254, 508, 762);
    }

    #[logic]
    #[ensures(crate::mc_entry(b_rgb_it32(), ms_rgb_it32()[0]) == Ok((128, 128, rgb_rgb_it32())))]
    pub fn msg_rgb_it32() {
        eff_rgb_it32();
        proof_assert!(crate::legacy_colour_model(crate::mentry_type(b_rgb_it32(), ms_rgb_it32()[0])) == Some(128u32));
        mr_rgb_it32();
        ilv_rgb_it32();
        crate::mc_entry_ok(b_rgb_it32(), ms_rgb_it32()[0], 128u32, pl_rgb_it32(), ct_rgb_it32_0(), ct_rgb_it32_1(), ct_rgb_it32_2(), rgb_rgb_it32());
    }

    #[logic(open)]
    pub fn expected_rgb_it32() -> Seq<u8> {
        pearlite! { Seq::create(49152, |i: Int| if i % 3 == 0 { 17u8 } else if i % 3 == 1 { 34u8 } else { 51u8 }) }
    }

    #[logic]
    #[ensures(rgb_rgb_it32() == expected_rgb_it32())]
    pub fn rgb_expected_rgb_it32() {
        proof_assert!(rgb_rgb_it32().ext_eq(expected_rgb_it32()));
    }

    #[logic]
    #[ensures(mc_model(b_rgb_it32(), ms_rgb_it32(), 0) == Ok((128, 128, expected_rgb_it32())))]
    pub fn agree_rgb_it32() {
        p_rgb_it32();
        proof_assert!(ms_rgb_it32().len() > 0);
        proof_assert!(mc_model(b_rgb_it32(), ms_rgb_it32(), 0) == mc_entry(b_rgb_it32(), ms_rgb_it32()[0]));
        msg_rgb_it32();
        rgb_expected_rgb_it32();
    }

